export const AGENT_WORKFLOW_MODES=[
 {agentType:4,key:'storyboard',title:'Seedance2.5 智能分镜模式',chain:'资产准备 → 站位图 → 提示词模板 → 生成视频',route:'storyboard',blocking_mode:'2d'},
 {agentType:2,key:'creation',title:'Seedance2.5 智能创作模式',chain:'资产准备 → 提示词模板 → 生成视频',route:'creation',blocking_mode:'skip',skip_blocking_reason:'Seedance2.5 智能创作模式跳过站位直出视频'},
 {agentType:5,key:'overseas_remake',title:'短剧出海转绘',chain:'上传源短剧，进入海外改编制作流程',route:'overseas_remake',blocking_mode:'skip'},
];
export function consumePendingAgentWorkflow(storage,projectId=null,episodeId=null){
 const raw=storage?.get?.('ai_tools_pending_agent_workflow');
 if(!raw||typeof raw!=='object')return null;
 const pMatch=!raw.projectId||!projectId||String(raw.projectId)===String(projectId);
 const eMatch=!raw.episodeId||!episodeId||String(raw.episodeId)===String(episodeId);
 if(!pMatch||!eMatch)return null;
 storage.put('ai_tools_pending_agent_workflow',null);
 const t=Number(raw.agentType);
 const preset=AGENT_WORKFLOW_MODES.find(m=>m.agentType===t||m.key===raw.agentType)||(t===1?{agentType:1,key:'storyboard',route:'storyboard',blocking_mode:'2d'}:t===3?{agentType:3,key:'creation',route:'creation',blocking_mode:'skip'}:AGENT_WORKFLOW_MODES[0]);
 return {projectId:raw.projectId||projectId,episodeId:raw.episodeId||episodeId,...preset};
}
// Preview follows the workflow's shot order and current working selections. A
// cleared selection must never fall back to an older formal binding or run.
export function intelligentPreviewClips(state,selections=[]){
 const byShot=new Map(selections.filter(row=>row.output_kind==='video').map(row=>[row.shot_id,row]));
 return state.units.filter(unit=>unit.kind==='shot').flatMap(unit=>{const row=byShot.get(unit.shot_id);return row?.media_id&&row.candidate_id?[{...row,unit_key:unit.unit_key,title:unit.title,duration_ms:row.trim_out_ms==null?null:row.trim_out_ms-(row.trim_in_ms||0)}]:[];});
}
export async function readIntelligentBatchProgress(api,projectBase,workflowId,batchId,previousJobs=[]){
 const value=await api(projectBase+'/intelligent-work-batches/'+batchId);
 const active=job=>!['succeeded','failed','cancelled','submission_unknown'].includes(job.status);
 let jobs=value.jobs?.length?value.jobs:previousJobs;
 // A manual/edit-preserved batch can still have running original jobs. The
 // first-cut receipt is immutable; read the original workflow's live job view.
 if(!['waiting','ready'].includes(value.status)&&previousJobs.some(active)){
  const workflow=await api(projectBase+'/intelligent-workflows/'+workflowId);
  jobs=workflow.batches.find(batch=>batch.id===batchId)?.jobs||jobs;
 }
 return {value,jobs,keepPolling:['waiting','ready','queued','running'].includes(value.status)||jobs.some(active)};
}
