     const titles={waiting:'等待原任务与素材',ready:'准备合成',manual:'手动剪辑',queued:'粗剪排队',running:'正在合成粗剪',succeeded:'首版已合成，待审片',failed:'合成失败，请查看原剪辑任务',cancelled:'合成已取消',edit_changed:'剪辑稿已更新，保留人工修改'};
